import {SIZE_CHART,CARD_HEIGHT_MM,pixelsPerMm,ringPixels} from './screen-sizing.js';
document.body.classList.add('mobile-app');
const css=document.createElement('link');css.rel='stylesheet';css.href='mobile.css';document.head.append(css);
const app=document.querySelector('#app');
const french=new URLSearchParams(location.search).get('lang')==='fr';
const en={title:'Find your perfect size',question:'How do you want to continue?',ai:'AI hand scan',preview:'Preview',aiDesc:'Take a photo of your hand with a standard-size card.',ring:'Measuring a ring',ringDesc:'We help you measure a ring that already fits you well.',or:'Or',guide:'See size guide',guideDesc:'Check the measurements in millimeters for each size.',legal:'Your photos stay on your device. Read our',privacy:'privacy policy',and:'and',terms:'measurement guide',handIntro:'Take a photo of your hand with a standard-size card.',examples:'See examples',private:'No personal data is stored. Images are used solely for measurement.',start:'Start now',cardIntro:'To get started, calibrate the tool with a standard-size card.',calibrate:'Place a standard-size card touching the top line and adjust the slider to match its size.',placeCard:'Place your card here ↑',equivalent:'You can use a bank, gift, or equivalent card.',next:'Next',ringIntro:'Use a flat-surfaced ring that fits you well as a reference and follow the instructions.',fitRing:'Place your ring over the circle and use the slider to fit its inner edge.',between:'If you are between two sizes, we recommend sizing up.',resultTitle:'Your size for this ring',valid:'Based on the reference size guide.',yourSize:'Your ring size',measured:'This is your measured ring size.',home:'Back to home',again:'Measure again',guideTitle:'Ring Size Guide',guideStep1:'1. Measure the internal diameter of a ring that fits the desired finger',zero:'Ensure your ruler starts at the 0mm mark.',guideStep2:'2. Use the table below to determine your ring size.',internal:'Internal Diameter (mm)',size:'Size',close:'Close',cardsTitle:'Some examples of valid cards',cards:["Driver’s license",'Loyalty card','National ID card','Membership card','Debit card','Hotel key card','Gift card','Public transport card','Credit card','Access badge'],back:'Back',cardScale:'Card height calibration',ringScale:'Ring size',engine:'Automatic hand sizing needs a connected AI engine. This standalone version supports the photo capture interface and physical ring measurement.',cameraError:'Camera unavailable or permission declined. You can choose a photo instead.',takePhoto:'Take a photo of your hand with a card',placeHand:'Place your hand below the card · Spread your fingers · Lay your phone flat',upload:'Choose photo',capture:'Take photo',card:'Card',hand:'Hand',notConnected:'AI sizing is not connected',notConnectedDesc:'Your photo is ready, but this version has no AI service to calculate finger sizes. Use the ring measurement method to get a size.',retry:'Retake photo',estimate:'Confirm the calibration against a physical card. Browser zoom, screen orientation and ring placement affect this estimate. Check with a physical sizing kit before ordering.',policy:'Privacy policy',privacyText:'Photos and camera frames remain in your browser. They are not uploaded or stored. Your ring size is calculated from your screen calibration and selected ring diameter. Camera access ends when you leave the capture screen.',termsTitle:'Measurement guide',termsText:'Hold a standard card in landscape orientation against the screen. Match the bottom line to its short edge (53.98 mm). Keep the same browser zoom and screen orientation. Match the circle to the ring’s inner edge. Screen sizing is an estimate. Aitaca’s automatic AI hand measurement service is not connected to this standalone version.'};
const fr={...en,title:'Trouvez votre taille idéale',question:'Comment souhaitez-vous continuer ?',ai:'Scan de la main par IA',preview:'Aperçu',aiDesc:'Photographiez votre main avec une carte de taille standard.',ring:'Mesurer une bague',ringDesc:'Nous vous aidons à mesurer une bague qui vous va bien.',or:'Ou',guide:'Voir le guide des tailles',guideDesc:'Consultez les mesures en millimètres pour chaque taille.',legal:'Vos photos restent sur votre appareil. Consultez notre',privacy:'politique de confidentialité',and:'et notre',terms:'guide de mesure',handIntro:'Prenez une photo de votre main avec une carte de taille standard.',examples:'Voir des exemples',private:'Aucune donnée personnelle n’est stockée. Les images servent uniquement à la mesure.',start:'Commencer',cardIntro:'Pour commencer, calibrez l’outil avec une carte de taille standard.',calibrate:'Posez une carte standard contre la ligne du haut et ajustez le curseur à sa taille.',placeCard:'Placez votre carte ici ↑',equivalent:'Utilisez une carte bancaire, cadeau ou équivalente.',next:'Suivant',ringIntro:'Utilisez une bague à surface plane qui vous va bien comme référence et suivez les instructions.',fitRing:'Posez votre bague sur le cercle et ajustez le curseur au bord intérieur.',between:'Entre deux tailles, nous recommandons de choisir la plus grande.',resultTitle:'Votre taille pour cette bague',valid:'Selon le guide des tailles de référence.',yourSize:'Votre taille de bague',measured:'Voici votre taille de bague mesurée.',home:'Retour à l’accueil',again:'Mesurer à nouveau',guideTitle:'Guide des tailles de bague',guideStep1:'1. Mesurez le diamètre intérieur d’une bague adaptée au doigt souhaité',zero:'Vérifiez que votre règle commence au repère 0 mm.',guideStep2:'2. Utilisez le tableau ci-dessous pour déterminer votre taille.',internal:'Diamètre intérieur (mm)',size:'Taille',close:'Fermer',cardsTitle:'Exemples de cartes valides',cards:['Permis de conduire','Carte de fidélité','Carte d’identité','Carte de membre','Carte de débit','Carte d’hôtel','Carte cadeau','Carte de transport','Carte de crédit','Badge d’accès'],back:'Retour',cardScale:'Calibration de la hauteur de la carte',ringScale:'Taille de bague',engine:'Le calcul automatique nécessite un moteur IA connecté. Cette version propose la capture photo et la mesure physique d’une bague.',cameraError:'Caméra indisponible ou autorisation refusée. Vous pouvez choisir une photo.',takePhoto:'Photographiez votre main avec une carte',placeHand:'Placez la main sous la carte · Écartez les doigts · Gardez le téléphone à plat',upload:'Choisir une photo',capture:'Prendre la photo',card:'Carte',hand:'Main',notConnected:'Le moteur IA n’est pas connecté',notConnectedDesc:'La photo est prête, mais aucun service IA n’est connecté pour calculer les tailles. Utilisez la méthode de mesure de bague.',retry:'Reprendre la photo',estimate:'Vérifiez la calibration avec une carte physique. Le zoom, l’orientation et le placement affectent l’estimation. Confirmez avec un kit de tailles.',policy:'Politique de confidentialité',privacyText:'Les photos restent dans votre navigateur et ne sont ni envoyées ni enregistrées. La taille de bague utilise la calibration de l’écran. La caméra s’arrête lorsque vous quittez la capture.',termsTitle:'Guide de mesure',termsText:'Placez une carte standard en orientation paysage sur l’écran. Ajustez la ligne inférieure à son petit côté (53,98 mm). Conservez le même zoom et la même orientation. Ajustez le cercle au bord intérieur de la bague. Le service IA Aitaca n’est pas connecté à cette version.'};
const copy=french?fr:en;const t=k=>copy[k];
let current='home',navigation=[],cardHeight=260,scale=null,selectedSize=9,cameraStream=null,photoUrl=null,calibrationWidth=null;
const sparkle='<svg viewBox="0 0 24 24"><path d="m14 2 1.8 5.2L21 9l-5.2 1.8L14 16l-1.8-5.2L7 9l5.2-1.8L14 2Z"/><path d="m5 12 1.3 3.7L10 17l-3.7 1.3L5 22l-1.3-3.7L0 17l3.7-1.3L5 12Z"/><path d="M21 1v4m-2-2h4"/></svg>';
const measureIcon='<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="m6 17 12-12m-6 0h6v6M6 11v6h6"/></svg>';
const lock='<svg viewBox="0 0 16 18" aria-hidden="true"><rect x="2" y="7" width="12" height="9" rx="1"/><path d="M4 7V5a4 4 0 0 1 8 0v2"/></svg>';
function stopCamera(){cameraStream?.getTracks().forEach(track=>track.stop());cameraStream=null;}
function go(screen,isBack=false){stopCamera();if(!isBack)navigation.push(current);current=screen;render();window.scrollTo(0,0);}
function back(){go(navigation.pop()||'home',true);}
function backButton(){return `<button class="mobile-back" id="back" aria-label="${t('back')}">‹</button>`;}
function dots(step){return `<nav class="mobile-dots" aria-label="${french?'Étapes de mesure':'Measurement steps'}">${[0,1,2].map(i=>`<button ${i===step?'aria-current="step"':''} aria-label="${i+1}" class="${i===step?'current':''}" data-step="${i}"></button>`).join('')}</nav>`;}
function action(id,label,outline=false){return `<button class="mobile-action${outline?' outline':''}" id="${id}">${t(label)}</button>`;}
function showDialog(title,body){const modal=document.querySelector('#policy');modal.classList.add('mobile-dialog');modal.querySelector('h2').textContent=title;modal.querySelector('div').innerHTML=body;modal.querySelector('.dismiss').className='mobile-action dismiss';modal.querySelector('.dismiss').textContent=t('close');modal.showModal();}
document.querySelectorAll('#policy .close,#policy .dismiss').forEach(b=>b.onclick=()=>document.querySelector('#policy').close());
function render(){document.documentElement.lang=french?'fr':'en';document.title=t('title');
if(current==='home'){
app.innerHTML=`<section class="mobile-screen mobile-menu"><h1>${t('title')}</h1><p class="menu-subtitle">${t('question')}</p><button class="menu-option featured" id="hand"><span class="menu-icon">${sparkle}</span><span class="option-body"><span class="option-heading"><strong>${t('ai')}</strong><small>${t('preview')}</small></span><span class="option-description">${t('aiDesc')}</span></span><span class="menu-chevron">›</span></button><button class="menu-option" id="ring"><span class="menu-icon" style="color:#88908f">${measureIcon}</span><span class="option-body"><span class="option-heading"><strong>${t('ring')}</strong></span><span class="option-description">${t('ringDesc')}</span></span><span class="menu-chevron">›</span></button><div class="menu-divider">${t('or')}</div><button class="menu-option menu-guide" id="guide"><span class="option-body"><span class="option-heading"><strong>${t('guide')}</strong></span><span class="option-description">${t('guideDesc')}</span></span><span class="menu-chevron">›</span></button><div class="mobile-legal">${t('legal')} <button data-policy="privacy">${t('privacy')}</button> ${t('and')} <button data-policy="terms">${t('terms')}</button>.</div></section>`;
document.querySelector('#hand').onclick=()=>go('hand-intro');document.querySelector('#ring').onclick=()=>go('card-intro');document.querySelector('#guide').onclick=()=>go('guide');
}else if(['hand-intro','card-intro','ring-intro'].includes(current)){
const hand=current==='hand-intro',card=current==='card-intro';const asset=hand?'onboarding_camera_img.svg':card?'onboarding_ring_size_flow.svg':'onboarding_ring_size_flow_2.svg';
app.innerHTML=backButton()+`<section class="mobile-screen onboarding-screen ${current}"><img class="onboarding-image" src="assets/${asset}" alt="${t(hand?'handIntro':card?'cardIntro':'ringIntro')}"><div class="onboarding-copy"><h1>${t(hand?'handIntro':card?'cardIntro':'ringIntro')}</h1>${hand?`<button class="examples-link" id="examples">${t('examples')}</button><div class="privacy-inline">${lock}<span>${t('private')}</span></div><div class="engine-notice">${t('engine')}</div>`:''}${action('start','start')}</div></section>`;
document.querySelector('#start').onclick=()=>go(hand?'capture':card?'calibrate':'ring-match');
document.querySelector('#examples')?.addEventListener('click',()=>showDialog(t('cardsTitle'),`<div class="examples">${copy.cards.map(x=>`<span>${x}</span>`).join('')}</div>`));
}else if(current==='calibrate'){
app.innerHTML=backButton()+dots(0)+`<section class="mobile-screen calibrate-screen"><h1>${t('calibrate')}</h1><div class="calibration-stage"><div class="card-placeholder"><span>${t('placeCard')}</span><small>${t('equivalent')}</small></div><input class="card-range" aria-label="${t('cardScale')}" type="range" min="100" max="400" value="${cardHeight}" step="0.5"></div><div class="mobile-bottom">${action('next','next')}</div></section>`;
const input=document.querySelector('.card-range'),stage=document.querySelector('.calibration-stage');const trackHeight=matchMedia('(max-height:720px)').matches?360:430;const update=()=>{cardHeight=Number(input.value);stage.style.setProperty('--card-height',`${cardHeight}px`);document.querySelector('#next').disabled=cardHeight<80;};update();
// Set the slider handle at the same Y coordinate as the physical card edge.
input.min=20;input.max=trackHeight-20;input.value=Math.min(cardHeight,trackHeight-20);update();input.oninput=update;
document.querySelector('#next').onclick=()=>{if(cardHeight<80)return;scale=pixelsPerMm(cardHeight);calibrationWidth=window.innerWidth;go('ring-intro');};
}else if(current==='ring-match'){
if(!scale){go('calibrate',true);return;}
app.innerHTML=backButton()+dots(1)+`<section class="mobile-screen ring-screen"><h1>${t('fitRing')}</h1><div class="ring-stage"><div class="ring-circle"><span class="arrow-start"></span><strong>${selectedSize}</strong><span class="arrow-end"></span></div><input class="ring-range" aria-label="${t('ringScale')}" type="range" min="6" max="14" step="1" value="${selectedSize}"></div><div class="between-note"><span>ⓘ</span>${t('between')}</div>${action('next','next')}</section>`;
const input=document.querySelector('.ring-range'),circle=document.querySelector('.ring-circle');const update=()=>{selectedSize=Number(input.value);const px=ringPixels(selectedSize,scale);circle.style.width=`${px}px`;circle.style.height=`${px}px`;circle.querySelector('strong').textContent=selectedSize;};input.oninput=update;update();document.querySelector('#next').onclick=()=>go('result');
}else if(current==='result'){
app.innerHTML=backButton()+dots(2)+`<section class="mobile-screen mobile-result"><h1>${t('resultTitle')}</h1><div class="product-notice"><span>♧</span><span>${t('valid')}</span></div><div class="result-size-row"><strong>${selectedSize}</strong><span class="result-tag">${t('yourSize')}</span></div><p class="result-description">${t('measured')}</p><div class="result-buttons">${action('home','home',true)}${action('again','again',true)}</div><p class="estimate-note">${t('estimate')}</p></section>`;
document.querySelector('#home').onclick=()=>{navigation=[];go('home',true);};document.querySelector('#again').onclick=()=>{navigation=['home','card-intro'];go('calibrate',true);};
}else if(current==='guide'){
app.innerHTML=backButton()+`<section class="mobile-screen guide-screen"><h1>${t('guideTitle')}</h1><h2>${t('guideStep1')}</h2><p class="ruler-subtitle">${t('zero')}</p><div class="guide-ruler"><img src="assets/rule.svg" alt="${t('internal')}"></div><h2>${t('guideStep2')}</h2><table><thead><tr><th scope="col">${t('internal')}</th><th scope="col">${t('size')}</th></tr></thead><tbody>${SIZE_CHART.map(row=>`<tr><td>${row.diameter.toFixed(1)}mm</td><td>${row.size}</td></tr>`).join('')}</tbody></table></section>`;
}else if(current==='capture'){
app.innerHTML=`<section class="capture-screen"><video autoplay playsinline muted id="camera-video"></video><div class="capture-toolbar"><button class="capture-back" id="back" aria-label="${t('back')}">‹</button><span>${t('card')}</span><span>|</span><span>${t('hand')}</span></div><div class="capture-guide"></div><div class="capture-guide hand-outline"></div><div class="capture-instruction">${t('placeHand')}</div><div class="capture-controls"><button class="capture-upload" id="upload">${t('upload')}</button><button class="shutter" id="shutter" aria-label="${t('capture')}" disabled></button></div><input id="photo-upload" class="capture-input" type="file" accept="image/*" capture="environment"><div class="capture-message" id="camera-message" hidden><h2>${t('takePhoto')}</h2><p id="camera-status"></p></div></section>`;
document.querySelector('#upload').onclick=()=>document.querySelector('#photo-upload').click();document.querySelector('#photo-upload').onchange=e=>{const file=e.target.files[0];if(!file)return;if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=URL.createObjectURL(file);go('photo-preview');};
document.querySelector('#shutter').onclick=()=>{const v=document.querySelector('#camera-video');if(!v.videoWidth)return;const canvas=document.createElement('canvas');canvas.width=v.videoWidth;canvas.height=v.videoHeight;canvas.getContext('2d').drawImage(v,0,0);canvas.toBlob(blob=>{if(!blob)return;if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=URL.createObjectURL(blob);go('photo-preview');},'image/jpeg',.9);};
openCamera();
}else if(current==='photo-preview'){
app.innerHTML=`<section class="capture-screen"><img class="captured-photo" src="${photoUrl}" alt="${t('takePhoto')}"><div class="capture-toolbar"><button class="capture-back" id="back" aria-label="${t('back')}">‹</button></div><div class="capture-message"><h2>${t('notConnected')}</h2><p>${t('notConnectedDesc')}</p>${action('measure-ring','ring')}${action('retake','retry',true)}</div></section>`;
document.querySelector('#measure-ring').onclick=()=>go('card-intro');document.querySelector('#retake').onclick=()=>go('capture');
}
document.querySelector('#back')?.addEventListener('click',back);
document.querySelectorAll('[data-policy]').forEach(button=>button.onclick=()=>showDialog(t(button.dataset.policy==='privacy'?'policy':'termsTitle'),`<p>${t(button.dataset.policy==='privacy'?'privacyText':'termsText')}</p>`));
document.querySelectorAll('[data-step]').forEach(button=>button.onclick=()=>{const step=Number(button.dataset.step);if(step===0)go('calibrate');else if(step===1&&scale)go('ring-match');else if(step===2&&scale)go('result');});
}
async function openCamera(){try{const next=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(current!=='capture'){next.getTracks().forEach(t=>t.stop());return;}cameraStream=next;const v=document.querySelector('#camera-video');v.srcObject=next;v.onloadedmetadata=()=>{document.querySelector('#shutter').disabled=false;};}catch{if(current==='capture'){document.querySelector('#camera-message').hidden=false;document.querySelector('#camera-status').textContent=t('cameraError');}}}
window.addEventListener('pagehide',()=>{stopCamera();if(photoUrl)URL.revokeObjectURL(photoUrl);});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopCamera();if(current==='capture')document.querySelector('#shutter').disabled=true;}else if(current==='capture'&&!cameraStream)openCamera();});
window.addEventListener('resize',()=>{if(scale&&calibrationWidth&&Math.abs(window.innerWidth-calibrationWidth)>30&&['ring-match','result'].includes(current)){scale=null;go('calibrate');}});
render();
